                        difference = d_mat[sbase + j] - row_sum
                        if not math.isfinite(difference):
                            raise ValueError(
                                "mha_batch backward intermediate"
                                " must be finite"
                            )
                        d_ij = saved_p[sbase + j] * difference
                        if not math.isfinite(d_ij):
                            raise ValueError(
                                "mha_batch backward intermediate"
                                " must be finite"
                            )
                        d_mat[sbase + j] = d_ij
        for b in range(B):
            for i in range(q):
                base = (b * q + i) * k
                for head in range(h):
                    for r in range(d):
                        acc = 0.0
                        for j in range(k):
